/** Small valid images, made with sharp, for upload and transformation tests. */

const bytes = (base64: string) => Uint8Array.from(atob(base64), (c) => c.charCodeAt(0));

/** A 40x20 JPEG, with Exif Make "Cirrus" and Model "Test Cam". */
export const JPEG = bytes(
  '',
);

/** A 2x1 PNG. */
export const PNG = bytes('iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAACXBIWXMAAAPoAAAD6AG1e1JrAAAADklEQVQImWP4z8DwH4QBEfcD/RSF9bkAAAAASUVORK5CYII=');
